-- ============================================================
-- seed_demo_more_students.sql
-- Soft reset of student data + 500 demo applicants spread
-- across all funnel stages.  Run AFTER schema.sql and
-- seed_users.sql.  Safe to re-run (clears any previous demo
-- students and demo support data first).
--
-- Stage distribution (matches user-confirmed ratios):
--   pending             :  65  (just registered, partial uploads)
--   documents           :  60  (in active doc review)
--   submitted           : 100  (all docs uploaded, awaiting review)
--   exam                :  75  (docs approved, exam slot assigned, not taken)
--   exam_passed         :  75  (in interview queue)
--   exam_failed         :  50  (back to documents step)
--   interview_complete  :  50  (awaiting result release)
--   released            :  25  (15 accepted + 5 waitlisted + 5 rejected)
--
-- Demo accounts:
--   email    : demo.student.001@student.plp.edu.ph .. demo.student.500@...
--   password : Student@123  (same hash as the existing seed_demo)
--
-- Soft reset semantics: all rows with users.role='student' are deleted
-- (FK cascades clear their applicants/documents/exam_results/...).
-- Staff, admin, SSO, dean, proctor accounts are untouched.
-- school_settings, departments, courses, passing scores untouched.
-- ============================================================

SET time_zone = '+08:00';

-- ------------------------------------------------------------
-- 0. Soft reset: clear all student data + demo support tables.
-- ------------------------------------------------------------
-- 0a. Drop all student-role users.  ON DELETE CASCADE on
--     applicants.user_id wipes their applicants row; further
--     cascades clean documents, exam_results, applicant_exam_slots,
--     interview_queue, admission_results, course_suggestions,
--     reschedule_logs, and notifications.
DELETE FROM `users` WHERE `role` = 'student';

-- 0b. Clear demo support rows (demo exam, demo exam rooms, demo
--     interview slots) so this seed is idempotent.  We use the
--     same labels/markers as seed_demo.sql so either seed can
--     re-run on top.
DELETE FROM `exam_slot_schedule`
    WHERE `room_label` REGEXP '^Rm-[0-9]+$'
      AND `school_year` = '2026-2027';
DELETE FROM `exams` WHERE `title` = 'PLP Entrance Exam (Demo)';
DELETE FROM `interview_slots` WHERE `location_notes` = 'Bring your applicant ID.';

-- 0c. Ensure email-verification columns exist (matches
--     core/automation.php :: ensure_email_verification_columns()).
ALTER TABLE `users`
  ADD COLUMN IF NOT EXISTS `email_verified`              TINYINT(1) NOT NULL DEFAULT 0 AFTER `is_active`,
  ADD COLUMN IF NOT EXISTS `email_verify_token`          VARCHAR(64) DEFAULT NULL AFTER `email_verified`,
  ADD COLUMN IF NOT EXISTS `email_verify_code`           VARCHAR(8) DEFAULT NULL AFTER `email_verify_token`,
  ADD COLUMN IF NOT EXISTS `email_verify_code_expires_at` DATETIME DEFAULT NULL AFTER `email_verify_code`,
  ADD COLUMN IF NOT EXISTS `email_verify_attempts`        TINYINT UNSIGNED NOT NULL DEFAULT 0 AFTER `email_verify_code_expires_at`,
  ADD COLUMN IF NOT EXISTS `email_verify_last_sent_at`    DATETIME DEFAULT NULL AFTER `email_verify_attempts`;

-- ------------------------------------------------------------
-- 1. Resolve staff user IDs by email so the seed survives any
--    future change in user AUTO_INCREMENT ordering.
-- ------------------------------------------------------------
SET @uid_admin     = (SELECT id FROM users WHERE email = 'admin@plp.edu.ph');
SET @uid_sso       = (SELECT id FROM users WHERE email = 'sso@plp.edu.ph');
SET @uid_staff_ccs = (SELECT id FROM users WHERE email = 'staff.ccs@plp.edu.ph');
SET @uid_staff_con = (SELECT id FROM users WHERE email = 'staff.con@plp.edu.ph');
SET @uid_staff_cba = (SELECT id FROM users WHERE email = 'staff.cba@plp.edu.ph');
SET @uid_staff_coe = (SELECT id FROM users WHERE email = 'staff.coe@plp.edu.ph');
SET @uid_staff_cas = (SELECT id FROM users WHERE email = 'staff.cas@plp.edu.ph');
SET @uid_staff_cen = (SELECT id FROM users WHERE email = 'staff.cen@plp.edu.ph');

-- ------------------------------------------------------------
-- 2. Demo entrance exam (single row; referenced by exam_results).
-- ------------------------------------------------------------
INSERT INTO `exams` (`id`, `title`, `description`, `passing_score`, `is_active`)
VALUES (1, 'PLP Entrance Exam (Demo)',
        'Auto-generated demo exam for the seed_demo_more_students data set.',
        50, 1)
ON DUPLICATE KEY UPDATE title = VALUES(title);

