-- ------------------------------------------------------------
-- 7. Map applicant idx -> applicant_id / user_id for later use.
-- ------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS _demo500_app_ids;
CREATE TEMPORARY TABLE _demo500_app_ids (
    idx          INT UNSIGNED PRIMARY KEY,
    email        VARCHAR(180) NOT NULL,
    applicant_id INT UNSIGNED NOT NULL,
    user_id      INT UNSIGNED NOT NULL
) ENGINE=Memory;
INSERT INTO _demo500_app_ids (idx, email, applicant_id, user_id)
SELECT CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(u.email, '@', 1), '.', -1) AS UNSIGNED),
       u.email, a.id, u.id
FROM users u
JOIN applicants a ON a.user_id = u.id
WHERE u.email LIKE 'demo.student.%@student.plp.edu.ph';

