-- Update `filled` counter on each room to match assignments above.
UPDATE `exam_slot_schedule` s
JOIN _demo500_exam_rooms r ON r.db_id = s.id
LEFT JOIN (
    SELECT slot_id, COUNT(*) AS c
    FROM applicant_exam_slots
    GROUP BY slot_id
) cc ON cc.slot_id = s.id
SET s.filled = COALESCE(cc.c, 0);

