-- ------------------------------------------------------------
-- 13. Welcome notification for every demo student.
-- ------------------------------------------------------------
INSERT INTO `notifications` (`user_id`, `type`, `title`, `message`, `is_read`, `created_at`)
SELECT u.id, 'info', 'Welcome to PLP Admissions',
       'Your application has been received. Please complete your documents.',
       0, u.created_at
FROM users u
WHERE u.email LIKE 'demo.student.%@student.plp.edu.ph';

-- Plus a result-released notification for each released applicant.
INSERT INTO `notifications` (`user_id`, `type`, `title`, `message`, `is_read`, `created_at`)
SELECT d.user_id, 'result',
       CASE ar.result
           WHEN 'accepted'   THEN 'You have been accepted!'
           WHEN 'waitlisted' THEN 'You have been waitlisted'
           ELSE 'Admission result released'
       END,
       'Your admission result is now available. Please log in to view details.',
       0, ar.released_at
FROM admission_results ar
JOIN _demo500_app_ids d ON d.applicant_id = ar.applicant_id;

